import requests
from collections.abc import Iterable

class ProxyIterable:
    def __getattr__(self, name):
        if name == "__iter__":
            return iter([1, 2, 3])
        raise AttributeError(name)

def test_proxy_iterable():
    data = ProxyIterable()
    print(f"isinstance(data, Iterable): {isinstance(data, Iterable)}")
    print(f"hasattr(data, '__iter__'): {hasattr(data, '__iter__')}")

    req = requests.Request('POST', 'http://httpbin.org/post', data=data)
    prepared = req.prepare()

    # If it's detected as a stream, Transfer-Encoding should be 'chunked' 
    # (unless it has a length)
    print(f"Headers: {prepared.headers}")

    if prepared.headers.get('Transfer-Encoding') == 'chunked':
        print("SUCCESS: Detected as stream")
    else:
        print("FAILURE: Not detected as stream")

if __name__ == "__main__":
    test_proxy_iterable()

